/**
 * Generates src/server/pdf/brand-assets.ts: the two PNGs printed on every PDF (logo and A-icon watermark) as base64.
 * Embedding them keeps PDF rendering independent of the file system, which on Vercel only holds traced files.
 *
 *   npm run build:pdf-assets          # regenerate after replacing the artwork
 *
 * A test fails if the generated file and public/static/assets disagree.
 */
import { readFileSync, writeFileSync } from 'node:fs'
import { join } from 'node:path'

export const ASSETS = { logoReverse: 'vora-reverse.png', watermark: 'vora-a-watermark.png' } as const
export const OUTPUT = join(process.cwd(), 'src/server/pdf/brand-assets.ts')

export function build(): string {
  const entries = Object.entries(ASSETS).map(([key, file]) => {
    const b64 = readFileSync(join(process.cwd(), 'public/static/assets', file)).toString('base64')
    return `  /** public/static/assets/${file} */\n  ${key}: '${b64}',`
  })
  return `// GENERATED by scripts/embed-pdf-assets.ts from public/static/assets. Do not edit by hand.\nexport const PDF_ASSETS = {\n${entries.join('\n')}\n} as const\n`
}

if (process.argv[1]?.endsWith('embed-pdf-assets.ts')) {
  writeFileSync(OUTPUT, build())
  console.log('Wrote', OUTPUT)
}
